#!/usr/bin/env python3
"""Execute entire original Options preferences with real Fumen notifier and Undo queue."""
import argparse,subprocess,tempfile,json,hashlib
from pathlib import Path
p=argparse.ArgumentParser()
for k in ['editor-root','reference-root','dotnet','output']:p.add_argument('--'+k,type=Path,required=True)
a=p.parse_args();pin='48e18f71655d0f0d86144c63239331833501fda2';fp='0fe292f9c0ef70fb77d61cb54316a7e78dbf3c89'
for path,rev in [(a.editor_root,pin),(a.reference_root/'Fumen',fp)]:assert subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()==rev
source=subprocess.check_output(['git','-C',str(a.editor_root),'show',pin+':StepManiaEditor/Preferences/PreferencesOptions.cs'],text=True,encoding='utf-8-sig')
event_source=subprocess.check_output(['git','-C',str(a.editor_root),'show',pin+':StepManiaEditor/EditorEvents/EditorEvent.cs'],text=True,encoding='utf-8-sig')
begin=event_source.index('public int GetStepColorRow()'); brace=event_source.index('{',begin); depth=1; end=brace+1
while depth:
 if event_source[end]=='{':depth+=1
 elif event_source[end]=='}':depth-=1
 end+=1
method=event_source[begin:end]
adapter='using System.Text.Json;using Fumen;using Fumen.Converters;using StepManiaEditor;\nnamespace StepManiaEditor {class Preferences {public static Preferences Instance=new();public PreferencesOptions PreferencesOptions=new();} class RowProbe {public int Row; public int RowRelativeToMeasureStart;public int TimeSignatureDenominator;public int GetRow()=>Row; METHOD}}\nclass Program {static void Main(){var factory=new PermissiveEnumJsonConverterFactory();PreferencesOptions.RegisterDefaultsForInvalidEnumValues(factory);var options=new JsonSerializerOptions{IncludeFields=true};options.Converters.Add(factory);var output=new List<object>();foreach(var json in JsonSerializer.Deserialize<string[]>("""["{}", "{\\"StepColorMethodValue\\": \\"note\\"}", "{\\"StepColorMethodValue\\": \\"nOtE\\"}", "{\\"StepColorMethodValue\\": \\" Beat \\"}", "{\\"StepColorMethodValue\\": \\"1\\"}", "{\\"StepColorMethodValue\\": \\"2\\"}", "{\\"StepColorMethodValue\\": \\"999\\"}", "{\\"StepColorMethodValue\\": \\"-1\\"}", "{\\"StepColorMethodValue\\": \\"Note, Beat\\"}", "{\\"StepColorMethodValue\\": \\"Stepmania, Note\\"}", "{\\"StepColorMethodValue\\": \\"future\\"}", "{\\"StepColorMethodValue\\": \\"1, Beat\\"}", "{\\"StepColorMethodValue\\": 1}", "{\\"StepColorMethodValue\\": 999}", "{\\"StepColorMethodValue\\": true}", "{\\"StepColorMethodValue\\": null}", "{\\"StepColorMethodValue\\": {}}", "{\\"StepColorMethodValue\\": []}"]""")){try{var p=JsonSerializer.Deserialize<PreferencesOptions>(json,options);Preferences.Instance.PreferencesOptions=p;var probe=new RowProbe{Row=300,RowRelativeToMeasureStart=32,TimeSignatureDenominator=8};output.Add(new{Input=JsonDocument.Parse(json).RootElement.Clone(),Raw=(int)p.StepColorMethodValue,Serialized=JsonSerializer.SerializeToElement(p,options).GetProperty("StepColorMethodValue"),Row=probe.GetStepColorRow(),Error=false});}catch(JsonException){output.Add(new{Input=JsonDocument.Parse(json).RootElement.Clone(),Error=true});}}Console.Write(JsonSerializer.Serialize(output));}}\n'
adapter=adapter.replace('METHOD',method)
with tempfile.TemporaryDirectory(prefix='audio-preferences-oracle-') as d:
 t=Path(d);(t/'Audio.cs').write_text(source);(t/'Program.cs').write_text(adapter);dll=a.reference_root/'Fumen/Fumen/bin/Release/net10.0/Fumen.dll';(t/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>disable</Nullable></PropertyGroup><ItemGroup><Reference Include="Fumen"><HintPath>{dll}</HintPath></Reference></ItemGroup></Project>');subprocess.run([str(a.dotnet),'build',str(t/'Oracle.csproj'),'-c','Release','--nologo','-v','quiet'],check=True);assembly=t/'bin/Release/net10.0/Oracle.dll';result=json.loads(subprocess.check_output([str(a.dotnet),str(assembly)],text=True));sha=hashlib.sha256(assembly.read_bytes()).hexdigest()
a.output.write_text(json.dumps(result,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps({'EditorCommit':pin,'FumenCommit':fp,'SourceSha256':hashlib.sha256(source.encode()).hexdigest(),'MethodSha256':hashlib.sha256(method.encode()).hexdigest(),'AdapterSha256':hashlib.sha256(adapter.encode()).hexdigest(),'AssemblySha256':sha,'FumenAssemblySha256':hashlib.sha256(dll.read_bytes()).hexdigest(),'Scope':'Whole original PreferencesOptions class with registered real Fumen enum converter and unchanged original EditorEvent.GetStepColorRow method in a row/property stand-in. No renderer simulation.'},indent=2)+'\n');print('Executed',len(result),'source StepColorMethod converter and original row method cases.')
